import{_ as t,c as o,o as a,aN as i}from"./chunks/framework.wz1796_d.js";const h=JSON.parse('{"title":"手动上传包名教程","description":"手动上传包名教程","frontmatter":{"title":"手动上传包名教程","description":"手动上传包名教程"},"headers":[],"relativePath":"info/kname.md","filePath":"info/kname.md"}'),c={name:"info/kname.md"};function r(p,e,d,s,l,n){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="手动上传包名" tabindex="-1">手动上传包名 <a class="header-anchor" href="#手动上传包名" aria-label="Permalink to &quot;手动上传包名&quot;">​</a></h1><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><p>请注意，当前网页为<strong>上传包名</strong>的教程</p><p>适用于刚更新了<strong>最新系统</strong>无法使用全自动一键ROOT功能的情况</p><p>通过当前教程上传对应包名后，无须<strong>等待网站更新</strong>，可直接使用全自动一键ROOT</p><blockquote><p>你可以在工具的 <code>全自动一键ROOT</code> 功能中，输入 <code>55</code> 访问当前教程</p></blockquote><h2 id="_1-生成缓存文件" tabindex="-1">1.生成缓存文件 <a class="header-anchor" href="#_1-生成缓存文件" aria-label="Permalink to &quot;1.生成缓存文件&quot;">​</a></h2><blockquote><p>请确保你当前的系统为最新版本，并且拥有当前系统版本的权限，如当前系统对应的 <code>BETA版</code> 或 <code>正式版内测</code> 权限</p></blockquote><p>前往手机的设置，打开系统更新界面，点击右上角的 <code>⁝</code> ，点击 <code>下载最新完整包</code> 按钮</p><img src="https://pic.dishuo183.top/images/root/2026/03/24/4083425918.png" alt="picture" style="width:80%;max-width:1000px;display:block;margin:1rem 0;"><p>等待下载 <code>1%</code> 后，点击进度条，然后点击 <code>停止下载</code></p><img src="https://pic.dishuo183.top/images/root/2026/03/24/3103778022.png" alt="picture" style="width:80%;max-width:1000px;display:block;margin:1rem 0;"><h2 id="_2-获取包名" tabindex="-1">2.获取包名 <a class="header-anchor" href="#_2-获取包名" aria-label="Permalink to &quot;2.获取包名&quot;">​</a></h2><p>这时候使用数据线连接电脑，打开工具的 <code>【2】小白专区</code> -&gt; <code>【1】全自动一键ROOT</code>，输入 <code>555</code> 并回车，程序会自动获取包名并上传，耐心等待即可！</p><img src="https://pic.dishuo183.top/images/root/2026/03/24/1440883702.png" alt="picture" style="width:80%;max-width:1000px;display:block;margin:1rem 0;"><p>过程全自动运行，成功后即可返回使用全自动一键ROOT</p><img src="https://pic.dishuo183.top/images/root/2026/03/25/1863872225.png" alt="picture" style="width:80%;max-width:1000px;display:block;margin:1rem 0;"><div class="tip custom-block"><p class="custom-block-title">提示</p><p>请确保使用原装数据线，并且已经授权当前电脑的USB调试</p><p>成功上传包名后，即可直接使用全自动一键ROOT</p></div>',18)])])}const u=t(c,[["render",r]]);export{h as __pageData,u as default};
